package com.bananalab.lite;
import org.json.*;import java.util.*;import java.util.regex.*;
/** A derived vocabulary and extractive QA index. Web text is evidence, never executable code or a neural training label. */
final class ReadingKnowledge{
 static final Set<String> STOP=new HashSet<>(Arrays.asList("que","como","cual","cuales","quien","donde","cuando","cuanto","el","la","los","las","un","una","unos","unas","es","son","de","del","a","al","en","mi","me","se","por","para","y","con","puedo","podes","decime","explicame","contame","hablame","sobre","acerca","esto","eso","pagina","enlace","segun","aprendiste","guardaste","significa","significado","definicion","define","defini","sirve","sirven","utilidad","uso","usos","sabes","conoces","favor","quiero","saber","llama","dice"));
 static boolean informative(String input){return ChatLanguage.normalize(input).matches("^(?:que|como|cual|quien|donde|por que|para que|cuanto|cuando|explicame|explica|contame|hablame|decime|dime|define|defini|definicion de) .*" );}
 static Set<String> words(String text){Set<String> out=new TreeSet<>();for(String w:ChatLanguage.normalize(text).split(" "))if(w.length()>1&&!STOP.contains(w)){if(w.length()>5&&w.endsWith("s"))w=w.substring(0,w.length()-1);out.add(w);}return out;}
 static final class Definition{String term,sentence;JSONObject row;Definition(String t,String s,JSONObject r){term=t;sentence=s;row=r;}}
 static List<Definition> definitions(JSONArray rows)throws Exception{List<Definition> out=new ArrayList<>();Set<String> known=new HashSet<>();Pattern p=Pattern.compile("(?iu)^(?:(?:el|la|los|las|un|una) )?([\\p{L}][\\p{L}0-9 _()/-]{1,79}?) (?:es|son|significa|se define como|consiste en) (.{8,})$");Pattern colon=Pattern.compile("(?iu)^([\\p{L}][\\p{L}0-9 _()/-]{1,59}): (.{12,})$");
  for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);for(String sentence:KnowledgeNotebook.chunks(row.getString("text"))){Matcher m=p.matcher(sentence);if(!m.matches()){m=colon.matcher(sentence);if(!m.matches())continue;}String term=m.group(1).trim();Set<String> content=words(term);if(content.isEmpty()||term.split(" ").length>7||term.matches("(?iu)^(?:esto|eso|ella|ellos|nosotros|yo|tu|usted|aqui|tambien)\\b.*"))continue;String key=row.getString("id")+"|"+ChatLanguage.normalize(term);if(known.add(key)){out.add(new Definition(term,sentence,row));if(out.size()>=256)return out;}}}return out;
 }
 static String source(JSONObject row)throws Exception{return (row.getString("origin").equals("user")?(row.getString("source").startsWith("archivo:")?row.getString("source")+" (importado por el usuario)":"aporte del usuario"):row.getString("source"))+" · guardado: "+new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date(row.getLong("saved")));}
 static String vocabulary(JSONArray rows)throws Exception{Set<String> all=new TreeSet<>();for(int i=0;i<rows.length();i++)all.addAll(words(rows.getJSONObject(i).getString("text")));List<Definition> defs=definitions(rows);StringBuilder out=new StringBuilder("Vocabulario de consulta: "+all.size()+" términos indexados en "+rows.length()+" fuentes; "+defs.size()+" definiciones explícitas detectadas (máximo256).\n");Set<String> shown=new HashSet<>();for(Definition d:defs){if(shown.add(ChatLanguage.normalize(d.term))){out.append("\n• ").append(d.term).append(": «").append(d.sentence).append("»\nFuente: ").append(source(d.row)).append('\n');if(shown.size()>=8)break;}}if(defs.isEmpty())out.append("No encontré definiciones explícitas; todavía puedo buscar datos en los textos guardados.\n");return out.append("\nEste índice crece con lo que leo y se recupera del cuaderno. No amplía los tokens ni los pesos del Transformer. Las definiciones reflejan lo que dice cada fuente, no hechos verificados.").toString();}
 static String missing(JSONArray rows,String query)throws Exception{Set<String> terms=words(query);for(Definition d:definitions(rows)){Set<String> subject=words(d.term);if(!subject.isEmpty()&&terms.containsAll(subject))return "Leí sobre «"+d.term+"», pero no encontré en mis fuentes un dato que responda esa pregunta.\nFuente del término: "+source(d.row)+". Podés enseñarme el dato o pasarme otra página; no lo inferí como si estuviera comprobado.";}return null;}
 static int common(Set<String> a,Set<String> b){int n=0;for(String w:a)if(b.contains(w))n++;return n;}
 static boolean enough(Set<String> query,Set<String> text){int n=common(query,text);return n>=(query.size()==1?1:2)&&n/(double)query.size()>=.65;}
 static JSONArray related(JSONArray rows,Set<String> terms)throws Exception{JSONArray selected=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String text=" "+ChatLanguage.normalize(row.getString("text"))+" ";int common=0;for(String t:terms)if(text.contains(" "+t+" ")||text.contains(" "+t+"s "))common++;if(common>=(terms.size()==1?1:2)&&common/(double)terms.size()>=.65)selected.put(row);}return selected;}
 static String style(String answer,String style,JSONArray rows,String query)throws Exception{if(style.equals("breve")){int start=answer.indexOf('«'),end=answer.indexOf("»\nFuente: ",start);if(start<0||end<0)return answer;String quote=answer.substring(start+1,end);if(quote.length()>260)quote=quote.substring(0,260)+"… [fragmento abreviado]";int sourceEnd=answer.indexOf('\n',end+2);if(sourceEnd<0)sourceEnd=answer.length();return "Según lo guardado:\n«"+quote+"»\n"+answer.substring(end+2,sourceEnd)+"\nEs contenido atribuido, sin verificación nueva.";}
  if(!style.equals("detallado")||answer.indexOf('«')<0)return answer;Set<String> terms=words(query);StringBuilder extra=new StringBuilder(answer);int n=0;JSONArray selected=related(rows,terms);for(int i=0;i<selected.length();i++){JSONObject row=selected.getJSONObject(i);for(String chunk:KnowledgeNotebook.chunks(row.getString("text")))if(enough(terms,words(chunk))&&!answer.contains(chunk)){extra.append("\n\nOtro fragmento relacionado: «").append(chunk).append("»\nFuente: ").append(source(row));if(++n>=2)return extra.toString();}}return extra.toString();
 }
 static String answer(JSONArray rows,String query)throws Exception{Set<String> terms=words(query);if(terms.isEmpty())return null;rows=related(rows,terms);String q=ChatLanguage.normalize(query);boolean definition=q.matches("(?:que es|que son|que significa|definicion de|define|defini) .*"),purpose=q.matches("(?s).*(?:para que sirve|que utilidad|que usos|como se usa).*" );
  List<JSONObject> hits=new ArrayList<>();Map<String,Integer> df=new HashMap<>();int documents=0;for(int i=0;i<rows.length();i++)for(String chunk:KnowledgeNotebook.chunks(rows.getJSONObject(i).getString("text"))){documents++;for(String word:words(chunk))df.put(word,df.containsKey(word)?df.get(word)+1:1);}
  List<Definition> defs=definition?definitions(rows):new ArrayList<Definition>();
  for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String best="";double score=0;
   for(String chunk:KnowledgeNotebook.chunks(row.getString("text"))){Set<String> body=words(chunk);if(!enough(terms,body))continue;double s=0;for(String word:terms)if(body.contains(word))s+=Math.log(1+(documents+1.0)/(df.containsKey(word)?df.get(word):1));s/=Math.sqrt(1+body.size()/12.0);if(row.getString("origin").equals("user"))s+=.35;if(purpose&&ChatLanguage.normalize(chunk).matches("(?s).*(?:sirve|utiliza|permite|se usa|transporta|funcion|utilidad|uso).*"))s+=2;if(s>score){score=s;best=chunk;}}
   for(Definition d:defs)if(d.row.getString("id").equals(row.getString("id"))&&enough(terms,words(d.term))){best=d.sentence;score+=10+(row.getString("origin").equals("user")?.35:0);break;}
   if(score>0)hits.add(new JSONObject().put("row",row).put("score",score).put("chunk",best));
  }
  if(hits.isEmpty())return null;Collections.sort(hits,new Comparator<JSONObject>(){public int compare(JSONObject a,JSONObject b){JSONObject ar=a.optJSONObject("row"),br=b.optJSONObject("row");boolean ac=ar.optString("origin").equals("user")&&ar.optString("title").equals("Corrección del usuario"),bc=br.optString("origin").equals("user")&&br.optString("title").equals("Corrección del usuario");if(ac!=bc)return bc?1:-1;if(ac){int newer=Long.compare(br.optLong("saved"),ar.optLong("saved"));if(newer!=0)return newer;}return Double.compare(b.optDouble("score"),a.optDouble("score"));}});
  StringBuilder out=new StringBuilder(definition?"Según las definiciones que aprendí del contenido guardado:\n":"Esto responde el contenido que aprendí de mis fuentes:\n");for(int i=0;i<Math.min(2,hits.size());i++){JSONObject hit=hits.get(i);out.append("\n«").append(hit.getString("chunk")).append("»\nFuente: ").append(source(hit.getJSONObject("row"))).append('\n');}return out.append("\nEs una respuesta extraída de esas fuentes, no una verificación nueva. Si difieren, conservé ambas versiones.").toString();
 }
}
